import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { writeFileSync } from 'node:fs';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
const repo='/Users/aantich/dev/oneringai',require=createRequire(repo+'/package.json');
const lib=process.env.REVIEW_SOURCE?(require('tsx/cjs'),require(repo+'/src/index.ts')):await import(repo+'/dist/index.js');
const {Agent,AgentContextNextGen,Connector,Vendor,FileContextStorage,InMemoryEvidenceStorage,ToolEvidenceMiddleware,StreamEventType}=lib;
const scope={ownerId:'alice',namespace:'third-review'},raw={operationId:'THIRD_REVIEW_914',body:'exact source observation '.repeat(1200)},results={mode:process.env.REVIEW_SOURCE?'source':'built-public'};
const tool={definition:{type:'function',function:{name:'probe',parameters:{type:'object',properties:{}}}},execute:async()=>raw,output:{effect:'write',summarize:()=> 'accepted'}};
const context=(storage,sessions)=>AgentContextNextGen.create({storage:sessions,model:'gpt-4o-mini',userId:scope.ownerId,features:{workingMemory:false,inContextMemory:false,evidence:true},plugins:{evidence:{storage}}});
const add=(c,report,evidence=report.evidence)=>{c.addUserMessage('once');c.addAssistantResponse([{type:'message',role:'assistant',content:[{type:'tool_use',id:'call',name:'probe',arguments:'{}'}]}]);c.addToolResults([{tool_use_id:'call',content:raw,state:'completed',evidence,outcome:report.outcome}]);};
async function stopStream(early=true){
 const storage=new InMemoryEvidenceStorage({scope});storage.put=async()=>{throw Error('offline')};let executions=0,calls=0;
 const provider={name:'review',capabilities:{text:true},validateConfig:async()=>true,listModels:async()=>[],getModelCapabilities:()=>({supportsTools:true,supportsVision:false,supportsJSON:true,supportsJSONSchema:true,maxTokens:128000,maxInputTokens:128000,maxOutputTokens:1024}),generate:async()=>{throw Error('unused')},async *streamGenerate(){calls++;if(calls===1){yield {type:StreamEventType.TOOL_CALL_START,response_id:'r',item_id:'i',tool_call_id:'call',tool_name:'probe'};yield {type:StreamEventType.TOOL_CALL_ARGUMENTS_DONE,response_id:'r',tool_call_id:'call',tool_name:'probe',arguments:'{}'};}else yield {type:StreamEventType.OUTPUT_TEXT_DELTA,response_id:'r',item_id:'i',output_index:0,content_index:0,sequence_number:0,delta:'done'};yield {type:StreamEventType.RESPONSE_COMPLETE,response_id:'r',status:'completed',usage:{input_tokens:10,output_tokens:5,total_tokens:15},iterations:1};}};
 Connector.create({name:'third-review-stream',vendor:Vendor.OpenAI,auth:{type:'none'},options:{provider}});
 const agent=Agent.create({connector:'third-review-stream',model:'gpt-4o-mini',userId:scope.ownerId,tools:[{...tool,execute:async()=>{executions++;return raw}}],emptyResponseRetry:{enabled:false},context:{model:'gpt-4o-mini',features:{workingMemory:false,inContextMemory:false,evidence:true},plugins:{evidence:{storage}}}});
 try{let seen=false;for await(const event of agent.stream('write once')){if(event.type===StreamEventType.TOOL_EXECUTION_DONE){seen=event.result===raw&&event.outcome.evidence.status==='storage_failed';if(early)break;}}
 const state=await agent.getContextState();const observation={executions,calls,completionEventHadRaw:seen,retainedHasRaw:JSON.stringify([...agent.context.getConversation(),...agent.context.getCurrentInput()]).includes(raw.body),snapshotHasRaw:JSON.stringify(state).includes(raw.body),storedRecords:(await storage.list()).entries.length};results[early?'streamStoppedAfterTool':'fullyDrainedStreamControl']=observation;assert.equal(seen,true);assert.equal(executions,1);assert.equal(observation.retainedHasRaw,!early);assert.equal(observation.snapshotHasRaw,!early);
 }finally{agent.destroy();Connector.remove('third-review-stream')}
}
async function restoreAfterRecovery(){for(const method of ['restoreState','load']){const directory=await mkdtemp(join(tmpdir(),'third-review-restore-')),storage=new InMemoryEvidenceStorage({scope}),sessions=new FileContextStorage({agentId:'third',baseDirectory:directory}),c=context(storage,sessions);const put=storage.put.bind(storage);storage.put=async()=>{throw Error('offline')};try{c.tools.register(tool);const report=await c.tools.executeWithOutcome('probe',{}, {callId:'call'});add(c,report);const snapshot=c.getState();if(method==='load')await c.save('checkpoint');storage.put=put;const recovered=await new ToolEvidenceMiddleware({storage}).record(tool,{}, {userId:'alice'},report.outcome,{value:raw});await c.acknowledgeToolEvidence('call',recovered.reference);if(method==='load')await c.load('checkpoint');else c.restoreState(snapshot);let error;try{await c.prepare()}catch(e){error=e.message}const count=[...c.getConversation(),...c.getCurrentInput()].flatMap(i=>i.type==='message'?i.content:[]).filter(x=>x.type==='tool_result'&&x.tool_use_id==='call').length;results[method==='load'?'loadAfterRecovery':'restoreAfterRecovery']={resultCount:count,error,rawRetained:JSON.stringify(c.getState()).includes(raw.body)};assert.equal(count,2);assert.match(error,/Duplicate final tool result/);}finally{c.destroy();await rm(directory,{recursive:true,force:true})}}}

async function receiptOnlyAdmission(){const storage=new InMemoryEvidenceStorage({scope}),c=context(storage);const put=storage.put.bind(storage);storage.put=async()=>{throw Error('offline')};try{c.tools.register(tool);const report=await c.tools.executeWithOutcome('probe',{}, {callId:'call'});storage.put=put;const receipt=await new ToolEvidenceMiddleware({storage}).record(tool,{}, {userId:'alice'},report.outcome);const control=context(storage);try{add(control,report);let error;try{await control.acknowledgeToolEvidence('call',receipt.reference)}catch(e){error=e.message}results.receiptOnlyAcknowledgementControl={error,stillProtected:JSON.stringify(control.getCurrentInput()).includes('storage_failed')};assert.match(error,/does not match/);}finally{control.destroy()}add(c,report,receipt);c.addAssistantResponse([]);const roll=await c.rollover({preserveRecentTurns:0,summarize:async()=> 'discarded'});const persisted=await storage.readRecord(receipt.reference);results.receiptOnlyAdmission={storedReceiptStatus:receipt.status,originalOutcomeEvidence:report.outcome.evidence.status,storedResultPresent:Object.hasOwn(persisted,'result'),rolled:roll.performed,retainedHasRaw:JSON.stringify(c.getConversation()).includes(raw.body)};assert.equal(roll.performed,true);assert.equal(results.receiptOnlyAdmission.storedResultPresent,false);assert.equal(results.receiptOnlyAdmission.retainedHasRaw,false);}finally{c.destroy()}}
async function failFastBatch(){const storage=new InMemoryEvidenceStorage({scope});storage.put=async()=>{throw Error('offline')};let writes=0,failures=0,calls=0;const provider={name:'batch',capabilities:{text:true},validateConfig:async()=>true,listModels:async()=>[],getModelCapabilities:()=>({supportsTools:true,supportsVision:false,supportsJSON:true,supportsJSONSchema:true,maxTokens:128000,maxInputTokens:128000,maxOutputTokens:1024}),generate:async()=>{calls++;return{id:'r',object:'response',model:'gpt-4o-mini',created_at:1,status:'completed',output_text:'',output:[{type:'message',role:'assistant',content:[{type:'tool_use',id:'call',name:'probe',arguments:'{}'},{type:'tool_use',id:'failed-call',name:'fail',arguments:'{}'}]}],usage:{input_tokens:10,output_tokens:5,total_tokens:15}}}};Connector.create({name:'third-review-batch',vendor:Vendor.OpenAI,auth:{type:'none'},options:{provider}});const agent=Agent.create({connector:'third-review-batch',model:'gpt-4o-mini',userId:scope.ownerId,errorHandling:{toolFailureMode:'fail'},toolExecutionTimeout:30,emptyResponseRetry:{enabled:false},tools:[{...tool,execute:async()=>{writes++;return raw}},{definition:{type:'function',function:{name:'fail',parameters:{type:'object',properties:{}}}},execute:async(_args,context)=>{failures++;return new Promise((_resolve,reject)=>{context.signal.addEventListener('abort',()=>reject(context.signal.reason),{once:true})})}}],context:{model:'gpt-4o-mini',features:{workingMemory:false,inContextMemory:false,evidence:true},plugins:{evidence:{storage}}}});try{let error;try{await agent.run('both')}catch(e){error=e.message}results.failFastBatch={writes,failures,calls,error,snapshotHasRaw:JSON.stringify(await agent.getContextState()).includes(raw.body),retainedHasRaw:JSON.stringify([...agent.context.getConversation(),...agent.context.getCurrentInput()]).includes(raw.body),storedRecords:(await storage.list()).entries.length};assert.equal(writes,1);assert.match(error,/timeout/);assert.equal(results.failFastBatch.snapshotHasRaw,false);}finally{agent.destroy();Connector.remove('third-review-batch')}}
await stopStream();await stopStream(false);await failFastBatch();await restoreAfterRecovery();await receiptOnlyAdmission();
writeFileSync('/tmp/oneringai-stage03-third-review-repro'+(process.env.REVIEW_SOURCE?'-source':'')+'.json',JSON.stringify(results,null,2)+'\n');console.log(JSON.stringify(results,null,2));
